create or replace function public.runtime_validate_selected_transfer_scope(p_source_sh_id uuid, p_scope jsonb, p_operation text) returns void language plpgsql security definer set search_path=public as $$ declare v_scope jsonb:=coalesce(p_scope,'{}'::jsonb); v_requested integer; v_matched integer; v_eligible integer; v_policy text:=upper(p_operation); begin if v_policy='INHERITABLE' then v_policy:='INHERITANCE'; end if; if v_policy not in ('INHERITANCE','SUCCESSION','LEGACY') then raise exception '%_REJECTED: invalid transfer operation',upper(p_operation); end if; if v_policy in ('SUCCESSION','LEGACY') then if not exists(select 1 from public.sh_instances s where s.sh_id=p_source_sh_id and s.status='deactivated') then raise exception 'TRANSFER_REJECTED: source SH must be end-of-life'; end if; else perform public.runtime_assert_active_sh(p_source_sh_id,'TRANSFER'); end if; v_requested:=(select count(*) from (select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'memory_ids','[]'::jsonb))) x); if v_requested>0 then select count(*) into v_matched from public.memories m where m.sh_id=p_source_sh_id and m.memory_id=any(array(select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'memory_ids','[]'::jsonb)))); if v_requested<>v_matched then raise exception '%_REJECTED: selected memory is not owned by source SH',v_policy; end if; select count(*) into v_eligible from public.memories m where m.sh_id=p_source_sh_id and m.memory_id=any(array(select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'memory_ids','[]'::jsonb)))) and m.transfer_policy=v_policy; if v_requested<>v_eligible then raise exception '%_REJECTED: selected memory is not eligible for this transfer operation',v_policy; end if; end if; v_requested:=(select count(*) from (select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'knowledge_ids','[]'::jsonb))) x); if v_requested>0 then select count(*) into v_matched from public.knowledge k where k.sh_id=p_source_sh_id and k.knowledge_id=any(array(select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'knowledge_ids','[]'::jsonb)))); if v_requested<>v_matched then raise exception '%_REJECTED: selected knowledge is not owned by source SH',v_policy; end if; select count(*) into v_eligible from public.knowledge k where k.sh_id=p_source_sh_id and k.knowledge_id=any(array(select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'knowledge_ids','[]'::jsonb)))) and k.transfer_policy=v_policy; if v_requested<>v_eligible then raise exception '%_REJECTED: selected knowledge is not eligible for this transfer operation',v_policy; end if; end if; v_requested:=(select count(*) from (select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'experience_ids','[]'::jsonb))) x); if v_requested>0 then select count(*) into v_matched from public.experiences e where e.sh_id=p_source_sh_id and e.experience_id=any(array(select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'experience_ids','[]'::jsonb)))); if v_requested<>v_matched then raise exception '%_REJECTED: selected experience is not owned by source SH',v_policy; end if; select count(*) into v_eligible from public.experiences e where e.sh_id=p_source_sh_id and e.experience_id=any(array(select distinct value::uuid from jsonb_array_elements_text(coalesce(v_scope->'experience_ids','[]'::jsonb)))) and e.transfer_policy=v_policy; if v_requested<>v_eligible then raise exception '%_REJECTED: selected experience is not eligible for this transfer operation',v_policy; end if; end if; end $$;
